export function buildHistoricalResearchSchedule(startISO = null) {
  return buildScheduleFor(HISTORICAL_RESEARCH_MODULES, startISO, HISTORICAL_RESEARCH_META.cadenceDays);
}

export function historicalResearchProgressSummary(progress = {}) {
  return progressSummaryFor(HISTORICAL_RESEARCH_MODULES, progress);
}

export function exportHistoricalResearchCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: HISTORICAL_RESEARCH_META,
    modules: buildHistoricalResearchSchedule(startISO),
    sessionFlow: HISTORICAL_RESEARCH_SESSION_FLOW,
  }, startISO);
}

/** The same voice and timeline gates the first history course carries (DR-0580 / DR-0597). */
export const historicalResearchVoiceFaults = historyVoiceFaults;
export const historicalResearchTimelineFaults = historyTimelineFaults;
export const historicalResearchWorkedCaseFaults = historyWorkedCaseFaults;
export { historyYearsNamed as historicalResearchYearsNamed, historyVoiceYears as historicalResearchVoiceYears };

/** Every distinct Scripture anchor the course names, in authored order (the crosslist's measured count). */
export function historicalResearchRefs(modules = HISTORICAL_RESEARCH_MODULES) {
  const out = [];
  for (const m of modules) for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) { const r = part.trim(); if (r && !out.includes(r)) out.push(r); }
  return out;
}

/** The whole course on one line of years — every lesson's dated record, merged and sorted. */
export function historicalResearchTimeline(modules = HISTORICAL_RESEARCH_MODULES) {
  const out = [];
  modules.forEach((m, order) => {
    for (const t of (m && m.timeline) || []) out.push({ ...t, lessonId: m.id, lessonTitle: m.title, order });
  });
  return out.sort((a, b) => (a.year - b.year) || (a.order - b.order));
}

/** Every distinct record the course quotes or dates, with the lessons that use it (the witness probes each on every push). */
export function historicalResearchSources(modules = HISTORICAL_RESEARCH_MODULES) {
  const map = new Map();
  for (const m of modules) {
    for (const v of m.voices || []) { const k = v.source.url; if (!map.has(k)) map.set(k, { ...v.source, lessons: new Set() }); map.get(k).lessons.add(m.id); }
    for (const t of m.timeline || []) if (t.source) { const k = t.source.url; if (!map.has(k)) map.set(k, { title: t.source.title, url: t.source.url, lessons: new Set() }); map.get(k).lessons.add(m.id); }
  }
  return [...map.values()].map((s) => ({ ...s, lessons: [...s.lessons] }));
}

